// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    Log log_;

    function setUp() public {
        log_ = new Log();
        c = new X_WALLET(address(log_));
    }

    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(log_));
        amount = bound(amount, 1 wei, 10 ether);

        uint256 n = 0;
        bool more = true;
        while (more) {
            try log_.History(n) returns (address, string memory, uint256, uint256) {
                n++;
            } catch {
                more = false;
            }
        }

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        uint256 nAfter = 0;
        bool more2 = true;
        while (more2) {
            try log_.History(nAfter) returns (address, string memory, uint256, uint256) {
                nAfter++;
            } catch {
                more2 = false;
            }
        }

        (address sender, , uint256 val, ) = log_.History(nAfter - 1);
        assertTrue(nAfter == n + 1 && sender == actor && val == amount);
    }
}
